import { jsPDF } from 'jspdf'
import autoTable from 'jspdf-autotable'

const AZUL = [6, 71, 148]   // #064794
const ROJO = [180, 39, 29]  // #B4271D
const GRIS = [110, 110, 110]
const GRIS_CLARO = [246, 248, 251]

const NIT_FEISEN = '900.595.456-2'
const RAZON_SOCIAL_FIJA = 'Feisen S.A.S.'
const CIUDAD_FIJA = 'Soacha'

// Logo horizontal oficial (icono + wordmark "FEISEN" a color), recortado del
// manual de marca — una sola imagen para evitar desalineaciones de dibujarlo
// a mano con texto + ícono por separado.
const FEISEN_LOGO_PNG = 'data:image/png;base64,'
const LOGO_ASPECT = 900 / 196

// IVA general en Colombia: 19 % (Art. 468 del Estatuto Tributario). Los precios unitarios de la
// orden se manejan SIN IVA; el IVA se calcula sobre el subtotal.
export const IVA_TARIFA = 0.19

const redondear2 = n => Math.round((Number(n) || 0) * 100) / 100

export function calcularTotalesOC(subtotal) {
  const sub = redondear2(subtotal)
  const iva = redondear2(sub * IVA_TARIFA)
  return { subtotal: sub, iva, total: redondear2(sub + iva) }
}

function copFmt(n) {
  return '$' + Number(n || 0).toLocaleString('es-CO', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
}

function fechaLarga(fechaISO) {
  const [y, m, d] = fechaISO.split('-').map(Number)
  return new Date(y, m - 1, d).toLocaleDateString('es-CO', { day: 'numeric', month: 'long', year: 'numeric' })
}

/**
 * Genera el PDF de una orden de compra y lo descarga.
 *
 * @param {object} orden - fila de `ordenes_compra` (numero, fecha, observaciones)
 * @param {object} proveedor - fila de `proveedores` (nombre, nit, contacto, telefono, email, direccion) o null
 * @param {Array}  items - filas de `orden_compra_items` (descripcion, unidad, cantidad, precio_unitario)
 * @param {object} pedido - { numero } del pedido de origen, o null
 * @param {string} generadoPor - nombre de quien generó la orden
 */
export function exportarOrdenCompraPDF(orden, proveedor, items, pedido, generadoPor) {
  const doc = new jsPDF({ unit: 'mm', format: 'letter' })
  const pageWidth  = doc.internal.pageSize.getWidth()
  const pageHeight = doc.internal.pageSize.getHeight()
  const margin = 15

  // ── Encabezado: logo horizontal oficial a la izquierda, N.° de orden destacado a la derecha ──
  const logoW = 62
  const logoH = logoW / LOGO_ASPECT
  try {
    doc.addImage(FEISEN_LOGO_PNG, 'PNG', margin, 10, logoW, logoH)
  } catch (e) { /* si por algún motivo la imagen no carga, seguimos sin bloquear el PDF */ }

  doc.setFont('helvetica', 'normal')
  doc.setFontSize(8.5)
  doc.setTextColor(...GRIS)
  doc.text(`${RAZON_SOCIAL_FIJA} · NIT ${NIT_FEISEN} · ${CIUDAD_FIJA}, Cundinamarca`, margin, 10 + logoH + 5)

  // Recuadro con el número de orden — bien visible, esquina superior derecha
  const boxW = 55, boxH = 20, boxX = pageWidth - margin - boxW, boxY = 8
  doc.setFillColor(...AZUL)
  doc.roundedRect(boxX, boxY, boxW, boxH, 2, 2, 'F')
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(9)
  doc.setTextColor(255, 255, 255)
  doc.text('ORDEN DE COMPRA', boxX + boxW / 2, boxY + 6, { align: 'center' })
  doc.setFontSize(15)
  doc.text(orden.numero, boxX + boxW / 2, boxY + 13.5, { align: 'center' })
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(8)
  doc.text(fechaLarga(orden.fecha), boxX + boxW / 2, boxY + 18, { align: 'center' })

  const yLinea = Math.max(33, 10 + logoH + 8)
  doc.setDrawColor(...AZUL)
  doc.setLineWidth(0.7)
  doc.line(margin, yLinea, pageWidth - margin, yLinea)

  // ── Proveedor ──
  let y = yLinea + 8
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(10)
  doc.setTextColor(...AZUL)
  doc.text('Proveedor', margin, y)
  y += 6
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(9.5)
  doc.setTextColor(30, 30, 30)
  doc.text(proveedor?.nombre || 'Sin proveedor asignado', margin, y)
  y += 5
  const lineasProveedor = []
  if (proveedor?.nit) lineasProveedor.push(`NIT: ${proveedor.nit}`)
  if (proveedor?.contacto) lineasProveedor.push(`Contacto: ${proveedor.contacto}`)
  if (proveedor?.telefono) lineasProveedor.push(`Tel: ${proveedor.telefono}`)
  if (lineasProveedor.length) {
    doc.setTextColor(...GRIS)
    doc.text(lineasProveedor.join('   ·   '), margin, y)
    y += 5
  }
  if (proveedor?.direccion) {
    doc.text(proveedor.direccion, margin, y)
    y += 5
  }
  if (pedido?.numero) {
    doc.setTextColor(...GRIS)
    doc.text(`Pedido de origen: ${pedido.numero}`, margin, y)
    y += 5
  }

  // ── Tabla de productos ──
  const filas = items.map((it, idx) => [
    String(idx + 1),
    it.descripcion,
    Number(it.cantidad).toLocaleString('es-CO'),
    it.unidad || '',
    copFmt(it.precio_unitario),
    copFmt(it.cantidad * it.precio_unitario),
  ])

  autoTable(doc, {
    startY: y + 4,
    head: [['#', 'Descripción', 'Cantidad', 'Unidad', 'Precio unitario', 'Subtotal']],
    body: filas,
    margin: { left: margin, right: margin },
    styles: { font: 'helvetica', fontSize: 9, textColor: [30, 30, 30], lineColor: [225, 225, 225] },
    headStyles: { fillColor: AZUL, textColor: [255, 255, 255], fontStyle: 'bold' },
    columnStyles: {
      0: { cellWidth: 8, halign: 'center' },
      2: { halign: 'right' },
      4: { halign: 'right' },
      5: { halign: 'right' },
    },
    alternateRowStyles: { fillColor: GRIS_CLARO },
  })

  const { subtotal, iva, total } = calcularTotalesOC(items.reduce((s, it) => s + it.cantidad * it.precio_unitario, 0))
  let yFinal = doc.lastAutoTable.finalY + 8

  // Si no cabe el bloque de totales + firma en la página, pasamos a una nueva
  if (yFinal > pageHeight - 80) {
    doc.addPage()
    yFinal = 25
  }

  // Bloque de totales: Subtotal, IVA 19 % y Total a pagar (recuadro azul institucional)
  const totW = 85
  const totX = pageWidth - margin - totW
  doc.setFont('helvetica', 'normal')
  doc.setFontSize(10)
  doc.setTextColor(...GRIS)
  doc.text('Subtotal', totX + 4, yFinal)
  doc.text(copFmt(subtotal), pageWidth - margin - 4, yFinal, { align: 'right' })
  yFinal += 6
  doc.text(`IVA (${Math.round(IVA_TARIFA * 100)}%)`, totX + 4, yFinal)
  doc.text(copFmt(iva), pageWidth - margin - 4, yFinal, { align: 'right' })
  yFinal += 4
  doc.setDrawColor(...AZUL)
  doc.setLineWidth(0.4)
  doc.line(totX, yFinal, pageWidth - margin, yFinal)
  yFinal += 3
  doc.setFillColor(...AZUL)
  doc.roundedRect(totX, yFinal, totW, 10, 1.5, 1.5, 'F')
  doc.setFont('helvetica', 'bold')
  doc.setFontSize(11)
  doc.setTextColor(255, 255, 255)
  doc.text('Total a pagar', totX + 4, yFinal + 6.8)
  doc.text(copFmt(total), pageWidth - margin - 4, yFinal + 6.8, { align: 'right' })
  yFinal += 10 + 8

  if (orden.observaciones) {
    doc.setFont('helvetica', 'bold')
    doc.setFontSize(9.5)
    doc.setTextColor(...GRIS)
    doc.text('Observaciones', margin, yFinal)
    yFinal += 5
    doc.setFont('helvetica', 'normal')
    const obsLines = doc.splitTextToSize(orden.observaciones, pageWidth - margin * 2)
    doc.text(obsLines, margin, yFinal)
    yFinal += obsLines.length * 4.5 + 6
  }

  // ── Firma ──
  const yFirma = Math.max(yFinal + 15, pageHeight - 40)
  doc.setDrawColor(180, 180, 180)
  doc.line(margin, yFirma, margin + 70, yFirma)
  doc.setFontSize(9)
  doc.setTextColor(...GRIS)
  doc.text('Autorizado por', margin, yFirma + 5)
  if (generadoPor) doc.text(generadoPor, margin, yFirma + 10)

  // ── Pie de página ──
  doc.setDrawColor(...ROJO)
  doc.setLineWidth(1)
  doc.line(0, pageHeight - 12, pageWidth, pageHeight - 12)
  doc.setFontSize(7.5)
  doc.setTextColor(160, 160, 160)
  doc.text(
    `${RAZON_SOCIAL_FIJA} · NIT ${NIT_FEISEN} · ${CIUDAD_FIJA}, Cundinamarca · Generado desde el sistema de inventario`,
    margin, pageHeight - 7
  )
  doc.text(orden.numero, pageWidth - margin, pageHeight - 7, { align: 'right' })

  doc.save(`${orden.numero}.pdf`)
}
